#!/usr/bin/env python3
"""Generate wire-only physical interfaces; original modules remain unchanged."""
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'rtl/qwen_sys/emb_hbm_20261008'
def generate():
    ports=['input wire clk, rst_n','input wire [524:0] link_i','output wire [524:0] link_o']
    ports += [f'output wire [287:0] cmd{n}' for n in range(32)]
    ports += [f'input wire [259:0] ret{n}' for n in range(32)]
    ports += ['output wire fault','output wire [7:0] fault_code','output wire [31:0] ce_cnt, ue_info']
    s='// Generated by tools/emb_hbm_port_sources.py. Wire aliases; no new latency.\n'
    s+='module ot_qfd_emb_strip_bus #(parameter integer ENABLE=0, STK=0, SQD=4, PFD=4, TXQ=4, OCR=4, ROW0=24427, TWIN=0, TWIN_ROFF=0, MUT=0)(\n '+',\n '.join(ports)+'\n);\n'
    s+='generate if (ENABLE != 0) begin: enabled\n wire [31:0] s_m,w_m,s_cr,e_v; wire s_we; wire [4:0] s_bank,s_col; wire [18:0] s_row; wire [255:0] w_d; wire [8255:0] e_d;\n'
    for n in range(32):
        s+=f' assign cmd{n}={{s_m[{n}],w_m[{n}],s_we,s_bank,s_col,s_row,w_d}};\n assign {{s_cr[{n}],e_v[{n}],e_d[{n}*258+:258]}}=ret{n};\n'
    s+=' ot_qfd_emb_strip #(.STK(STK),.NPC(32),.SQD(SQD),.PFD(PFD),.TXQ(TXQ),.OCR(OCR),.ROW0(ROW0),.TWIN(TWIN),.TWIN_ROFF(TWIN_ROFF),.MUT(MUT)) core(\n .clk(clk),.rst_n(rst_n),.i_v(link_i[524]),.i_d(link_i[523:1]),.o_cr(link_i[0]),\n .o_v(link_o[524]),.o_d(link_o[523:1]),.i_cr(link_o[0]),\n .s_m(s_m),.w_m(w_m),.s_we(s_we),.s_bank(s_bank),.s_col(s_col),.s_row(s_row),.w_d(w_d),\n .s_cr(s_cr),.e_v(e_v),.e_d(e_d),.fault(fault),.fault_code(fault_code),.ce_cnt(ce_cnt),.ue_info(ue_info));\n end else begin: disabled\n'
    for n in range(32): s+=f' assign cmd{n}=288\'b0;\n'
    s+=" assign link_o=525'b0; assign fault=1'b0; assign fault_code=8'b0; assign ce_cnt=32'b0; assign ue_info=32'b0;\n end endgenerate\nendmodule\n"
    (OUT/'ot_qfd_emb_strip_bus.sv').write_text(s)
    orig=(OUT/'ot_qfd_emb_pc.sv').read_text()
    header=orig[:orig.index(' wire c_v')]
    header=header.replace('module ot_qfd_emb_pc #(', 'module ot_qfd_emb_pc_bus #(')
    header=header.replace(' input wire s_v,w_v,s_we,input wire [4:0] s_bank,s_col,\n input wire [18:0] s_row,input wire [255:0] w_d,\n output wire s_credit,e_v,output wire [257:0] e_d,',' input wire [287:0] emb_cmd, output wire [259:0] emb_ret,')
    s='// Generated by tools/emb_hbm_port_sources.py. Wire aliases; no new latency.\n'+header
    s+=' ot_qfd_emb_pc #(.ENABLE(ENABLE),.PC(PC),.PHASE(PHASE),.SQD(SQD),.S_STARVE(S_STARVE),.TWIN(TWIN),.TWIN_ROFF(TWIN_ROFF)) core(\n'
    names=['clk','rst_n','hclk','hrst_n','cmd_v','cmd','read_credit','cmd_credit','row_v','row_op','row_bank','row_row','col_v','col_we','col_sr','col_bank','col_col','busy','r_v','r_d','wd','kv_v','kv_d','fault_core','fault_hbm']
    entries=[f'.{n}({n})' for n in names]
    entries += ['.s_v(emb_cmd[287])','.w_v(emb_cmd[286])','.s_we(emb_cmd[285])','.s_bank(emb_cmd[284:280])','.s_col(emb_cmd[279:275])','.s_row(emb_cmd[274:256])','.w_d(emb_cmd[255:0])','.s_credit(emb_ret[259])','.e_v(emb_ret[258])','.e_d(emb_ret[257:0])']
    s+=' '+',\n '.join(entries)+'\n );\nendmodule\n'
    (OUT/'ot_qfd_emb_pc_bus.sv').write_text(s)
if __name__=='__main__': generate()
